function evaluarPosfija(tokens) {
  const pila = [];
  for (const t of tokens) {
    if ('+-*/'.includes(t) && t.length === 1) {
      const b = pila.pop(), a = pila.pop();
      if (t === '+') pila.push(a + b);
      else if (t === '-') pila.push(a - b);
      else if (t === '*') pila.push(a * b);
      else pila.push(Math.trunc(a / b));
    } else {
      pila.push(Number(t));
    }
  }
  return pila.pop();
}

solution.python:
def evaluarPosfija(tokens):
    pila = []
    for t in tokens:
        if t in ('+', '-', '*', '/'):
            b, a = pila.pop(), pila.pop()
            if t == '+': pila.append(a + b)
            elif t == '-': pila.append(a - b)
            elif t == '*': pila.append(a * b)
            else: pila.append(int(a / b))
        else:
            pila.append(int(t))
    return pila.pop()
